pw.test("获取 discover/movie 多页电影数据（按投票数排序）", async () => {
  const TOKEN = "Bearer eyJhbGciOiJIUzI1NiJ9.eyJhdWQiOiIyZGNlYjM3NTkwNThiNzdjZGEyNTQzMTQ1MTQ2ZjdmMSIsIm5iZiI6MTc3OTg2MjczMC4xNDMwMDAxLCJzdWIiOiI2YTE2OGNjYTU4M2NmODgzYzViNDY3ODciLCJzY29wZXMiOlsiYXBpX3JlYWQiXSwidmVyc2lvbiI6MX0.VsTg3MMVoCRoOSFgoW4S06G1yBdVIb6hrWwTTk0Lj8I"; // ⚠️ 替换成你的真实 Token
  const page_start = 1;
  const page_stop = 2;
  //const sort_value = 'vote_count.desc';//投票降序
  const sort_value = 'vote_average.desc';//评分降序

  // 语言代码 → 中文名称映射表
  const languageMap = {
    'en': '英语', 'zh': '中文', 'ja': '日语', 'ko': '韩语', 'fr': '法语',
    'de': '德语', 'es': '西班牙语', 'it': '意大利语', 'ru': '俄语', 'pt': '葡萄牙语',
    'ar': '阿拉伯语', 'hi': '印地语', 'th': '泰语', 'vi': '越南语', 'id': '印尼语',
    'tr': '土耳其语', 'nl': '荷兰语', 'pl': '波兰语', 'sv': '瑞典语', 'he': '希伯来语'
  };
  
  // 类型 ID → 中文名称映射表（常见类型）
  const genreMap = {
    28: "动作", 12: "冒险", 16: "动画", 35: "喜剧", 80: "犯罪",
    18: "剧情", 10751: "家庭", 14: "奇幻", 36: "历史", 27: "恐怖",
    10402: "音乐", 9648: "悬疑", 10749: "爱情", 878: "科幻", 53: "惊悚",
    10752: "战争", 37: "西部"
  };
  
  // 存储所有数据行
  let logLines = [];
  
  // 表头
  logLines.push(sort_value);
  logLines.push("页码\t序号\t标题\t上映日期\t语言\t类型\t评分\t投票数\t热度\tID\t简介");
  
  //let globalIndex = 0;  // 全局序号（跨页累计）
  let globalIndex = (page_start-1)*20;  // 全局序号（跨页累计）
  let globalNum = 0;  // 全局数量（跨页累计）
  // 循环获取第 1 页和第 2 页
  for (let page = page_start; page <= page_stop; page++) {
    //console.log(`正在获取第 ${page} 页...`);
    
    try {
      const response = await fetch(
        `https://api.themoviedb.org/3/discover/movie?page=${page}&sort_by=${sort_value}&language=zh-CN`,
        {
          headers: {
            'Authorization': TOKEN
          }
        }
      );
      
      const data = await response.json();
      
      if (data.results && data.results.length > 0) {
        data.results.forEach(movie => {
          globalIndex++;
          globalNum++;
          
          // 处理语言：代码转中文名称
          const language = languageMap[movie.original_language] || movie.original_language.toUpperCase();
          
          // 处理类型：ID 转中文名称
          const genreNames = movie.genre_ids
            //?.map(id => genreMap[id])
            ?.slice(0, 2).map(id => genreMap[id])
            .filter(Boolean)
            .join(',') || '';
          
          // 处理简介：去除换行符
          const overview = movie.overview 
            //? movie.overview.replace(/\r?\n|\r/g, ' ').substring(0, 200)
            ? movie.overview.replace(/\r?\n|\r/g, ' ')
            : '暂无简介';
          
          // 按制表符分隔输出
          logLines.push(
            `${page}\t` +
            `${globalIndex}\t` +
            `${movie.title || '未知'}\t` +
            //`${movie.release_date || '未知'}\t` +
            `${movie.release_date.slice(0, 4) || '未知'}\t` +
            `${language}\t` +
            `${genreNames}\t` +
            `${movie.vote_average || 0}\t` +
            `${movie.vote_count || 0}\t` +
            `${movie.popularity || 0}\t` +
            `${movie.id || ''}\t` +
            `${overview}`
          );
        });
        
        console.log(`第 ${page} 页获取成功，获得 ${data.results.length} 部电影`);
      } else {
        console.warn(`第 ${page} 页无数据`);
      }
      
    } catch (error) {
      console.error(`获取第 ${page} 页失败:`, error.message);
    }
  }
  
  // 一次性打印所有数据
  console.log(`\n===== 共获取 ${globalNum} 部电影 =====\n`);
  console.log(logLines.join("\n"));
});

